def gainRowsMC3E (q : ℕ) (r : Bool) (j : ℕ) : Polynomial ℤ :=
 if r then rowSMFFD (fibRowsMC3E q) j+fibRowsMC3E (q+1) j
 else rowShiftMFFD 0 1 (fibRowsMC3E q) j+rowSMFFD (fibRowsMC3E (q+1)) j

def secondCorrectionMC3E (q : ℕ) (r : Bool) : Polynomial ℤ :=
 X^2*(X+1)^secondExponentMC3E q r*
   (C (secondConstantMC3E r)+C (secondSlopeMC3E q r)*X)

def perturbGapMC3E (j t h : ℕ) (a b c : ℝ) : ℝ[X] :=
 (cutPolyMFEE h (perturbLiftMC3E j (t+1) b))^2-
 cutPolyMFEE h (perturbLiftMC3E j t a)*cutPolyMFEE h (perturbLiftMC3E j (t+2) c)

def secondMarginValueMC3E (t d B : ℚ) (r : Bool) : ℚ :=
 let j := d+(if r then 6 else 5)
 let V := secondBoundNumeratorMC3E t d r
 B^2*j*(t+j+4)/((t+4)^2*(t+5))-
 2*V/(t+1)*B*(t+j+4)*(t+j+5)*
 ((t+6)*(t+7)+4*j*(t+j+6))/((t+4)*(t+5)*(t+6)*(t+7))-(V/(t+1))^2

def secondBorderScalarMC3E (t d B : ℚ) (r : Bool) : ℚ :=
 let j := d+(if r then 6 else 5)
 B*j*((t+6)*(t+7)+4*(j-1)*(t+j+5))*(t+5)^2*(t+6)*(t+1)-
 secondBoundNumeratorMC3E t d r*(t+j+5)*((t+5)*(t+6)+4*j*(t+j+5))^2*(t+4)*(t+7)

def thirdQuadraticMC3E (q : ℕ) (r : Bool) : ℤ :=
 if r then 4*(q.choose 2:ℤ)+4*((q+1).choose 2:ℤ)-12*q+8
 else 4*((q+1).choose 2:ℤ)-4*q

def thirdCorrectionMC3E (q : ℕ) (r : Bool) : Polynomial ℤ :=
 X^2*(X+1)^thirdExponentMC3E q r*
 (C (thirdConstantMC3E r)+C (thirdLinearMC3E q r)*X+C (thirdQuadraticMC3E q r)*X^2)
